-- ════════════════════════════════════════════════════════════════════════
-- PROPUESTAS DE VIDEO · 3 por ejercicio, para que TÚ elijas
-- ════════════════════════════════════════════════════════════════════════
-- Dónde: Supabase del CRM → SQL Editor → pegar todo → Run.
-- Es idempotente: correrlo otra vez reemplaza las propuestas, no las duplica.
--
-- NO cambia ningún video. Solo guarda candidatos; los eliges en el CRM:
--   Entrenamiento → Galería → «🎬 Video» en cada tarjeta, o
--   «🎬 Revisar videos uno a uno» arriba (recorre la lista filtrada).
--
-- Cómo se buscaron: en YouTube, por el nombre en inglés del ejercicio. Se
-- quedaron los que dicen el ejercicio en el título, duran poco (se prefiere
-- ≤ 60 s), se pueden ver dentro de la app (incrustables) y, a igualdad, los
-- que NO tienen voz. Se descartan compilaciones, «top 5», rutinas, etc.
-- El video que el ejercicio ya tiene no sale como propuesta.
--
-- 232 ejercicios revisados · 229 con 3 propuestas · 2 con menos · 1 sin ninguna.
-- ════════════════════════════════════════════════════════════════════════
begin;

create table if not exists ejercicio_video_propuestas (
  id uuid primary key default gen_random_uuid(),
  ejercicio_id uuid not null references ejercicios(id) on delete cascade,
  orden int not null,
  ref text not null,                 -- id del video de YouTube
  titulo text,
  canal text,
  duracion_seg int,
  habla boolean,                     -- true = tiene voz / explicación
  vertical boolean,                  -- formato de celular (shorts)
  created_at timestamptz default now(),
  unique (ejercicio_id, ref)
);
create index if not exists ejercicio_video_propuestas_ej_idx on ejercicio_video_propuestas (ejercicio_id, orden);

alter table ejercicio_video_propuestas enable row level security;
-- El coach ve las propuestas de SUS ejercicios.
drop policy if exists ejercicio_video_propuestas_coach on ejercicio_video_propuestas;
create policy ejercicio_video_propuestas_coach on ejercicio_video_propuestas for all
  using (exists (select 1 from ejercicios e where e.id = ejercicio_id and e.user_id = auth.uid()))
  with check (exists (select 1 from ejercicios e where e.id = ejercicio_id and e.user_id = auth.uid()));

create temp table _prop (alias text, nombre text, orden int, ref text, titulo text, canal text, duracion_seg int, habla boolean, vertical boolean) on commit drop;

-- Se reemplazan las propuestas de los ejercicios que vienen aquí.
delete from ejercicio_video_propuestas v
 using ejercicios e
 where v.ejercicio_id = e.id
   and exists (select 1 from _prop p where e.alias = p.alias or lower(e.nombre) = lower(p.nombre));

select e.id, p.orden, p.ref, p.titulo, p.canal, p.duracion_seg, p.habla, p.vertical
  from _prop p
  join ejercicios e on (e.alias = p.alias or lower(e.nombre) = lower(p.nombre))
 where not coalesce(e.archivado, false)
on conflict (ejercicio_id, ref) do nothing;

-- Resumen: cuántos ejercicios tienen propuestas.
select count(distinct ejercicio_id) as ejercicios_con_propuestas, count(*) as propuestas
  from ejercicio_video_propuestas;

commit;
